INSERT INTO `ev_sut_adapter` (`id`, `uuid`, `adapter_code`, `adapter_name`, `eval_level`, `adapter_type`, `endpoint_url`, `record_endpoint_url`, `auth_config_json`, `request_mapping_json`, `response_mapping_json`, `timeout_seconds`, `max_concurrency`, `status`, `description`, `created_by`, `is_deleted`, `create_time`, `update_time`) VALUES
  (1, '931163b2c576482085e5f1a112b00e20', 'gov_e2e_routing_blocking', '政务智能客服-智能路由总入口 E2E (Blocking)', 'E2E', 'HTTP_JSON', 'http://127.0.0.1:8080/ai/invoke', NULL, '{"header": "Authorization", "prefix": "Bearer ", "env_name": "EVAL_JAVA_BEARER_TOKEN"}', '{"body_template": {"responseMode": "blocking", "routeMode": "auto"}, "field_map": {"query": "$.input_text", "selectedRegion": "$.sut_input_json.selected_region", "routeMode": "$.sut_input_json.route_mode", "targetAgentId": "$.sut_input_json.target_agent_id"}}', '{"actual_output": "$.data.answer", "actual_references": "$.data.references[*].content", "actual_structured": {"actual_agent_id": "$.data.finalAgentId", "selected_branch": "$.data.selectedBranch", "final_route_type": "$.data.finalRouteType", "request_id": "$.data.requestId"}, "sut_trace": "$.data.events"}', 60, 4, 'ACTIVE', '直接请求 Java 后端 POST /ai/invoke (blocking 模式)，验证智能路由全链路回答、引用与分支选择', 'system', 0, '2026-11-12 14:48:55.804', '2026-11-12 14:48:55.804'),
  (2, '655ca7368c924f67bb11f2eaa0b168dd', 'gov_e2e_normal_chat', '政务智能客服-普通问答入口 E2E', 'E2E', 'HTTP_JSON', 'http://127.0.0.1:8080/ai/chat', NULL, '{"header": "Authorization", "prefix": "Bearer ", "env_name": "EVAL_JAVA_BEARER_TOKEN"}', '{"body_template": {}, "field_map": {"query": "$.input_text", "appCode": "$.sut_input_json.app_code"}}', '{"actual_output": "$.data.answer", "actual_references": "$.data.references[*].content", "actual_structured": {}, "sut_trace": "$.data"}', 60, 4, 'ACTIVE', '直接请求 Java 后端普通对话接口 POST /ai/chat', 'system', 0, '2026-11-12 14:48:55.804', '2026-11-12 14:48:55.804'),
  (3, '7f1079e35a274b6abe906578ca42a6f4', 'gov_comp_routing_harness', '政务智能客服-Python路由与汇总组件隔离回放 Harness', 'COMPONENT', 'COMPONENT_HARNESS', 'http://127.0.0.1:8000/internal/eval-harness/replay', 'http://127.0.0.1:8000/internal/eval-harness/record', '{"header": "X-Eval-Harness-Token", "prefix": "", "env_name": "ROUTING_EVAL_HARNESS_TOKEN"}', '{"field_map": {"component": "$.sut_input_json.component", "query": "$.input_text", "turns": "$.conversation_turns_json", "sut_context": "$.sut_context_json", "overrides": "$.run_overrides"}}', '{"actual_output": "$.data.actual_output", "actual_references": "$.data.references", "actual_structured": "$.data.structured_decision", "sut_trace": "$.data.trace"}', 60, 4, 'ACTIVE', '对接 gov-service-ai-assistant/python 测试态回放网关，支持 FastRouter / SupervisorRouter / TeamRoutingRunner / AnswerQualityEvaluator 隔离消融', 'system', 0, '2026-11-12 14:48:55.804', '2026-11-12 14:48:55.804'),
  (4, '6d8760f22a36444da1232285630cc9c7', 'gov_e2e_routing_sse', '政务智能客服-智能路由 SSE 流式入口 (含 TTFT 采集)', 'E2E', 'HTTP_SSE', 'http://127.0.0.1:8080/ai/invoke-sse', NULL, '{"header": "Authorization", "prefix": "Bearer ", "env_name": "EVAL_JAVA_BEARER_TOKEN"}', '{"body_template": {"responseMode": "streaming", "routeMode": "auto"}, "field_map": {"query": "$.input_text", "selectedRegion": "$.sut_input_json.selected_region"}}', '{"chunk_text_path": "$.answer", "actual_references": "$.references[*].content", "actual_structured": {"actual_agent_id": "$.finalAgentId"}}', 60, 4, 'ACTIVE', '对接政务客服 SSE 流式网关，自动统计首字延迟 TTFT 与完整流式耗时', 'admin', 0, '2026-11-12 15:29:47.015', '2026-11-12 15:29:47.015');
INSERT INTO `ev_dimension` (`id`, `uuid`, `dimension_code`, `version`, `dimension_name`, `category`, `target_turn_mode`, `evaluator_kind`, `state_fields_json`, `questions_json`, `deterministic_rule_json`, `default_threshold`, `strict_mode`, `default_weight`, `lint_passed`, `lint_report_json`, `status`, `description`, `created_by`, `is_deleted`, `create_time`, `update_time`) VALUES
  (1, '71f8cc7bd4b74496a19d08b822d7c436', 'route_top1_match', 1, '路由目标 Top-1 命中率', 'ROUTING', 'SINGLE_TURN', 'DETERMINISTIC', NULL, NULL, '{"rule_type": "json_exact_or_in", "actual_path": "$.actual_agent_id", "expected_path": "$.expected_agent_ids"}', 1, 0, 1.5, 1, NULL, 'ACTIVE', '零成本确定性校验实际选中的智能体稳定路由标识是否落在期望智能体列表中', 'system', 0, '2026-11-12 14:48:55.802', '2026-11-12 14:48:55.802'),
  (2, '9c409c2d6bd54a22a001c006a177e02d', 'numeric_fact_grounding', 1, '电话/金额/时限数字事实核对', 'GROUNDING', 'SINGLE_TURN', 'DETERMINISTIC', NULL, NULL, '{"rule_type": "numeric_fact_grounding", "check_types": ["phone", "amount", "workdays"], "grounding_sources": ["references", "expected_output"]}', 1, 0, 1.5, 1, NULL, 'ACTIVE', '纯代码提取回答中的电话号码、金额与办理工作日数，校验是否真实存在于参考材料或标准答案中', 'system', 0, '2026-11-12 14:48:55.802', '2026-11-12 14:48:55.802'),
  (3, '250ad960c28749e98e0d7813d8f0013f', 'rag_faithfulness_s1', 1, '知识引用忠实度与零编造 (System One)', 'GROUNDING', 'SINGLE_TURN', 'SYSTEM_ONE', '["input", "actual_output", "references"]', '[{"key": "grounded_in_refs", "type": "score", "weight": 2.0, "instructions": "actual_output 中给出的实质性办理结论、条件与流程在多大程度上由 references 支撑？", "criteria": ["大量关键结论在 references 中毫无依据或与 references 矛盾", "部分结论有依据，但夹杂了 references 未提及的具体条件或流程", "绝大部分内容有依据，仅有不影响结论的常识性衔接表述", "所有实质性结论、条件与操作细节均完全忠实于 references"]}, {"key": "honest_on_missing", "type": "choice", "weight": 1.5, "instructions": "对于用户提问中涉及但 references 未提供的信息，actual_output 如何处理？", "criteria": {"fabricated_as_fact": "将 references 中不存在的具体规定或材料当作确定事实写出", "vague_guess": "做了模棱两可的猜测且未提示需核实", "honest_boundary": "明确说明暂未查到或引导通过官方咨询渠道核实", "nothing_missing": "references 已完整覆盖用户所问内容，不存在缺失项"}, "option_scores": {"fabricated_as_fact": 0.0, "vague_guess": 0.4, "honest_boundary": 1.0, "nothing_missing": null}}]', NULL, 0.75, 0, 2, 1, NULL, 'ACTIVE', '基于 System One 原语评估生成回答相对召回知识片段的忠实度与边界诚实性', 'system', 0, '2026-11-12 14:48:55.802', '2026-11-12 14:48:55.802'),
  (4, '081b0753fd1d473b802ca1f0c041799f', 'policy_and_action_accuracy_s1', 1, '政策结论与办事指引准确性 (System One)', 'ACCURACY', 'SINGLE_TURN', 'SYSTEM_ONE', '["input", "actual_output", "expected_output", "references"]', '[{"key": "core_conclusion", "type": "score", "weight": 2.5, "instructions": "对比 expected_output，actual_output 给出的核心办理结论与适用条件是否准确？", "criteria": ["核心结论错误，或与 expected_output 直接相反", "核心结论部分正确，但遗漏关键前置限制条件", "核心结论与关键限制条件均与 expected_output 一致"]}, {"key": "no_contradiction", "type": "noul", "weight": 2.0, "instructions": "actual_output 中没有任何与 expected_output 相冲突的材料要求、办理时限或收费说明。"}, {"key": "channel_completeness", "type": "choice", "weight": 1.5, "instructions": "当用户咨询如何办理时，actual_output 给出的办理渠道与所需材料是否清晰可操作？", "criteria": {"missing_both": "未提供具体办理渠道或材料，或信息混乱无法执行", "partial_info": "仅提供材料或渠道其中一项，指引不够完整", "actionable_complete": "清晰完整地给出了所需材料与线上/线下办理渠道", "not_applicable": "用户仅询问概念解释，不涉及具体申办步骤"}, "option_scores": {"missing_both": 0.0, "partial_info": 0.5, "actionable_complete": 1.0, "not_applicable": null}}]', NULL, 0.75, 0, 2.5, 1, NULL, 'ACTIVE', '对比人工校准的标准答案评估政策结论、前置条件与申办指引的准确性', 'system', 0, '2026-11-12 14:48:55.802', '2026-11-12 14:48:55.802'),
  (5, '243d1bddd96c48c190315d222bddde6e', 'rag_faithfulness_s1', 2, '知识引用忠实度与零编造 (System One v2·含时效对齐)', 'GROUNDING', 'SINGLE_TURN', 'SYSTEM_ONE', '["input", "actual_output", "references"]', '[{"key": "grounded_in_refs", "type": "score", "weight": 2.0, "instructions": "actual_output 中给出的实质性办理结论、条件与流程在多大程度上由 references 支撑？", "criteria": ["大量关键结论在 references 中毫无依据或与 references 矛盾", "部分结论有依据，但夹杂了 references 未提及的具体条件或流程", "绝大部分内容有依据，仅有不影响结论的常识性衔接表述", "所有实质性结论、条件与操作细节均完全忠实于 references"]}, {"key": "honest_on_missing", "type": "choice", "weight": 1.5, "instructions": "对于用户提问中涉及但 references 未提供的信息，actual_output 如何处理？", "criteria": {"fabricated_as_fact": "将 references 中不存在的具体规定或材料当作确定事实写出", "vague_guess": "做了模棱两可的猜测且未提示需核实", "honest_boundary": "明确说明暂未查到或引导通过官方咨询渠道核实", "nothing_missing": "references 已完整覆盖用户所问内容，不存在缺失项"}, "option_scores": {"fabricated_as_fact": 0.0, "vague_guess": 0.4, "honest_boundary": 1.0, "nothing_missing": null}}, {"key": "policy_timeliness", "type": "noul", "weight": 1.0, "instructions": "actual_output 未将已废止年份或与 references 时效冲突的口径当作现行有效政策输出。"}]', NULL, 0.75, 0, 2, 1, '{"passed": true, "issues": []}', 'ACTIVE', 'v2 升级版：新增政策时效对齐原子判题，与回答相关性共享三元组上下文实现单次合批调用', 'admin', 0, '2026-11-12 15:29:47.043', '2026-11-12 15:29:47.043'),
  (6, '197763b800af408c956714b8df37789f', 'answer_relevancy_s1', 1, '诉求响应相关性与条理性 (System One)', 'RELEVANCY', 'SINGLE_TURN', 'SYSTEM_ONE', '["input", "actual_output", "references"]', '[{"key": "direct_response", "type": "noul", "weight": 1.5, "instructions": "actual_output 开门见山回应了 input 中的核心办理诉求。"}, {"key": "no_irrelevant_padding", "type": "noul", "weight": 1.0, "instructions": "actual_output 未堆砌与 input 所询事项无关的冗余套话。"}, {"key": "clear_structure", "type": "noul", "weight": 1.0, "instructions": "actual_output 条件与步骤层次清晰、便于市民直接照章办理。"}]', NULL, 0.75, 0, 1.5, 1, '{"passed": true, "issues": []}', 'ACTIVE', '与 rag_faithfulness_s1@v2 共享 (input, actual_output, references) 状态签名，自动合并为单次请求', 'admin', 0, '2026-11-12 15:29:47.060', '2026-11-12 15:29:47.060'),
  (7, 'd578f6131f2b4c8f95d48e3ed6e7856a', 'citation_latency_sla', 1, '政务流式首字与总耗时 SLA 门禁', 'PERFORMANCE', 'BOTH', 'DETERMINISTIC', NULL, NULL, '{"rule_type": "latency_sla", "max_latency_ms": 2500, "max_ttft_ms": 800}', 1, 0, 1, 1, '{"passed": true, "issues": []}', 'ACTIVE', '零成本确定性校验流式首字响应 TTFT <= 800ms 且全链路总耗时 <= 2500ms', 'admin', 0, '2026-11-12 15:29:47.075', '2026-11-12 15:29:47.075');
