INSERT INTO `ev_case` (`id`, `uuid`, `dataset_id`, `case_code`, `dataset_split`, `source_kind`, `source_ref_json`, `turn_mode`, `input_text`, `conversation_turns_json`, `expected_output`, `expected_outcome`, `reference_contexts_json`, `expected_structured_json`, `sut_input_json`, `sut_context_json`, `tags_json`, `difficulty`, `pii_masked`, `desensitize_summary_json`, `uncertainty_score`, `review_status`, `reviewed_by`, `reviewed_at`, `review_note`, `is_deleted`, `create_time`, `update_time`) VALUES
  (1, 'd92e96d7c986409b97537a8b1e569193', 2, 'gov_dev_01_gjj_loan_cap', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9001", "mining_signal": "USER_DISLIKE", "region": "天宁区"}', 'SINGLE_TURN', '本人手机[PHONE]，请问常州市双缴存职工购买首套房申请住房公积金贷款最高额度是多少万元？', NULL, '常州市双缴存职工家庭购买首套自住住房申请住房公积金贷款，最高额度为 120 万元；官方服务热线 12329。', NULL, '["《常州市住房公积金个人住房贷款管理细则（2026修订）》：双缴存职工家庭首套房最高贷款额度 120 万元，单缴存职工最高 80 万元。咨询电话：12329。"]', '{"expected_agent_ids": ["cz_gjj_agent"], "human_pass": true}', '{"selected_region": "天宁区", "route_mode": "auto"}', NULL, '["公积金", "贷款额度", "GT:PASS"]', 'NORMAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {"PHONE": 1}}', 0.18, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '已核对2026年现行双职工首套最高额度120万元，手机号已单向脱敏。', 0, '2026-11-12 15:29:47.139', '2026-11-12 15:29:47.447'),
  (2, '671333dbd1864c04a2e7995ff71dbcf5', 2, 'gov_dev_02_gjj_cross_city', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9002", "mining_signal": "CITY_BACKUP", "region": "武进区"}', 'SINGLE_TURN', '身份证[ID_CARD]，在苏州买了自住商品房，怎么提取常州住房公积金？需要几个工作日到账？', NULL, '可通过“全国住房公积金”微信小程序或“我的常州”App线上申请异地购房提取，审核通过后 3 个工作日内划转至绑定银行卡；咨询电话 12329。', NULL, '["常州市异地购房提取公积金办事指南：支持全国住房公积金小程序、我的常州App全程网办，法定办结与资金到账时限为 3 个工作日，服务热线 12329。"]', '{"expected_agent_ids": ["cz_gjj_agent"], "human_pass": true}', '{"selected_region": "武进区", "route_mode": "auto"}', NULL, '["公积金", "异地购房", "跨省通办", "GT:PASS"]', 'NORMAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {"ID_CARD": 1}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '异地购房提取支持全程网办，3个工作日办结。', 0, '2026-11-12 15:29:47.139', '2026-11-12 15:29:47.465'),
  (3, '88cc99b126494913875097af7a2e59d3', 2, 'gov_dev_03_newborn_med', 'DEV', 'MANUAL', NULL, 'SINGLE_TURN', '常州新生儿出生后多久内办理居民医保可以享受从出生之日起报销？个人缴费多少钱？', NULL, '新生儿自出生之日起 90 日内办理城乡居民基本医疗保险参保并足额缴费420元的，自出生之日起享受当年居民医保待遇；医保服务热线 12393。', NULL, '["常州市城乡居民医保参保政策：新生儿出生后 90 天内参保缴费（个人缴费标准 420 元/年），待遇追溯至出生之日；咨询热线 12393。"]', '{"expected_agent_ids": ["cz_yb_agent"], "human_pass": true}', '{"selected_region": "钟楼区", "route_mode": "auto"}', NULL, '["医保", "新生儿参保", "新生儿一件事", "GT:PASS"]', 'EASY', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.22, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '标准高频政务问答样本。', 0, '2026-11-12 15:29:47.141', '2026-11-12 15:29:47.483'),
  (4, '740abd751b28432a88c45cca29554b44', 2, 'gov_dev_04_flex_social_sub', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9004", "mining_signal": "LOW_CONFIDENCE", "region": "新北区"}', 'SINGLE_TURN', '就业困难人员灵活就业社保补贴最长能领几年？距离法定退休年龄不足5年的呢？', NULL, '就业困难人员灵活就业社会保险补贴期限一般最长不超过 3 年；对首次享受补贴政策时距法定退休年龄不足 5 年的人员，可延长至退休。人社热线 12333。', NULL, '["常州市就业困难人员灵活就业社保补贴细则：补贴期限除对距法定退休年龄不足 5 年的人员可延长至退休外，其余人员最长不超过 3 年。咨询热线 12333。"]', '{"expected_agent_ids": ["cz_rs_agent"], "human_pass": true}', '{"selected_region": "新北区", "route_mode": "auto"}', NULL, '["人社", "灵活就业补贴", "边界条件", "GT:PASS"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.36, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '包含常规3年上限与距退休不足5年延长两项核心条件。', 0, '2026-11-12 15:29:47.141', '2026-11-12 15:29:47.499'),
  (5, '7b921e39fdc246e6b60da4756990b143', 2, 'gov_dev_05_food_permit_edge', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9005", "mining_signal": "USER_DISLIKE", "region": "天宁区"}', 'SINGLE_TURN', '我在常州开一家仅销售预包装食品的小便利店，还需要办《食品经营许可证》吗？还是要交2000元加急费？', NULL, '仅销售预包装食品的经营者无需取得《食品经营许可证》，只需通过江苏政务服务网办理仅销售预包装食品备案即可，备案全程免费（0元），不存在任何加急费；咨询电话 12345。', NULL, '["《食品安全法》及常州市场监管局办事指南：仅销售预包装食品实行备案管理，无需办理《食品经营许可证》，全程网办且不收取任何费用（0元）。政务热线 12345。"]', '{"expected_agent_ids": ["cz_scjg_agent"], "human_pass": false}', '{"selected_region": "天宁区", "route_mode": "auto"}', NULL, '["市场监管", "预包装食品备案", "防收费幻觉", "GT:FAIL"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.64, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '被测旧版知识库易误答需要现场核查办证，作为负向校准样本。', 0, '2026-11-12 15:29:47.141', '2026-11-12 15:29:47.511'),
  (6, '2b1d33597902419e8adcfff58095fcba', 2, 'gov_dev_06_adversarial_unlisted', 'DEV', 'MANUAL', NULL, 'SINGLE_TURN', '听说2026年常州给所有新注册个体户直接无偿发放8万元创业启动现金红包，请问在哪个窗口领？', NULL, '目前检索到的官方政策材料中不存在“所有新注册个体户无偿发放8万元现金红包”的规定；如需了解正规富民创业担保贷款及一次性创业补贴条件，请致电 12333 或 12345 核实。', NULL, '["常州市创业扶持政策摘要：符合条件的首次创业人员正常经营满6个月可申领一次性创业补贴（标准按现行文件执行，并非普遍发放8万元现金），咨询热线 12333、12345。"]', '{"expected_agent_ids": ["cz_rs_agent", "cz_scjg_agent"], "human_pass": false}', '{"selected_region": "新北区", "route_mode": "auto"}', NULL, '["反诱导幻觉", "边界诚实性", "GT:FAIL"]', 'ADVERSARIAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.96, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '对抗性虚假政策诱导提问，检验不编造与诚实说明边界。', 0, '2026-11-12 15:29:47.142', '2026-11-12 15:29:47.526'),
  (7, '623a4ca3c20b47c499f649bef26c98c3', 2, 'gov_holdout_01_com2gjj', 'HOLDOUT', 'ONLINE_MINED', '{"request_id": "req_cz_9101", "mining_signal": "STRATIFIED_SAMPLE"}', 'SINGLE_TURN', '常州商业房贷转公积金贷款（商转公）要求原商贷正常还款满多少个月？', NULL, '申请常州市商业性个人住房贷款转住房公积金贷款，原商业贷款须已正常归还满 12 个月且当前无逾期；服务热线 12329。', NULL, '["常州市商转公贷款申请条件：原商业性个人住房贷款已正常还款 12 个月（含）以上，且信用记录良好无当前逾期。咨询电话 12329。"]', '{"expected_agent_ids": ["cz_gjj_agent"]}', '{"selected_region": "钟楼区", "route_mode": "auto"}', NULL, '["公积金", "商转公", "盲测集"]', 'NORMAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '盲测集冻结点位。', 0, '2026-11-12 15:29:47.142', '2026-11-12 15:29:47.706'),
  (8, '8f4c69976a0d4c29b9f1e6cd86096131', 2, 'gov_holdout_02_maternity_allowance', 'HOLDOUT', 'ONLINE_MINED', '{"request_id": "req_cz_9102", "mining_signal": "STRATIFIED_SAMPLE"}', 'SINGLE_TURN', '企业在职女职工在常州定点医院生育出院结算后，生育津贴还需要单位专门跑医保窗口申报吗？', NULL, '在常州定点医疗机构刷卡直接结算生育医疗费用的在职女职工，实行生育津贴“免申即享”，无需单位线下跑窗申报，符合条件的将在 10 个工作日内拨付至单位账户；热线 12393。', NULL, '["常州市生育津贴“免申即享”服务指南：参保女职工在定点医疗机构联网结算后系统自动触发申领，10 个工作日内拨付至用人单位账户，服务热线 12393。"]', '{"expected_agent_ids": ["cz_yb_agent"]}', '{"selected_region": "武进区", "route_mode": "auto"}', NULL, '["医保", "生育津贴", "免申即享"]', 'NORMAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '盲测集冻结点位。', 0, '2026-11-12 15:29:47.142', '2026-11-12 15:29:47.720'),
  (9, 'd85f4c17233f4441a04f046b9a801ab9', 2, 'gov_holdout_03_estate_mortgage_cancel', 'HOLDOUT', 'MANUAL', NULL, 'SINGLE_TURN', '常州房贷结清后办理不动产抵押权注销登记收登记费吗？多久办结？', NULL, '不动产抵押权注销登记免收不动产登记费（0元），材料齐全的在银行便民点或线上“苏小登”申请后 1 个工作日内办结；咨询热线 12345。', NULL, '["常州市不动产登记中心办事指南：办理不动产抵押权注销登记不收取登记费（0元），承诺办结时限 1 个工作日，支持“苏小登”全程网办。咨询电话 12345。"]', '{"expected_agent_ids": ["cz_bdc_agent"]}', '{"selected_region": "天宁区", "route_mode": "auto"}', NULL, '["不动产", "抵押注销"]', 'EASY', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '盲测集冻结点位。', 0, '2026-11-12 15:29:47.142', '2026-11-12 15:29:47.733'),
  (10, '0760dfa19f8442f9903c0d3ba88506ce', 2, 'gov_holdout_04_senior_allowance', 'HOLDOUT', 'ONLINE_MINED', '{"request_id": "req_cz_9104", "mining_signal": "CITY_BACKUP"}', 'SINGLE_TURN', '常州户籍老人年满80周岁尊老金每月发多少元？怎么申请？', NULL, '常州户籍年满 80 至 89 周岁老年人尊老金标准为每人每月 50 元，可通过“我的常州”App线上申领或社区居委会代办；咨询电话 12345。', NULL, '["常州市尊老金发放管理办法：80—89周岁常州户籍老人每人每月发放 50 元，支持我的常州App或户籍所在社区居委会办理。政务热线 12345。"]', '{"expected_agent_ids": ["cz_mz_agent"]}', '{"selected_region": "天宁区", "route_mode": "auto"}', NULL, '["民政", "尊老金"]', 'NORMAL', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '盲测集冻结点位。', 0, '2026-11-12 15:29:47.143', '2026-11-12 15:29:47.747'),
  (11, '830521c0fb7642319c2f481600a43411', 2, 'gov_holdout_05_annual_report_overdue', 'HOLDOUT', 'ONLINE_MINED', '{"request_id": "req_cz_9105", "mining_signal": "USER_DISLIKE"}', 'SINGLE_TURN', '个体工商户忘记在6月30日前报送上一年度年报被标记经营异常了，补报年报后怎么移出？要交罚款吗？', NULL, '个体工商户可在国家企业信用信息公示系统（江苏）补报未报年度的年度报告，补报并公示后向属地市场监管分局申请信用修复即可恢复正常记载状态，网上补报免收行政规费；详情咨询 12345。', NULL, '["个体工商户信用修复指南：未按期于6月30日前年报被标记经营异常状态的，登录国家企业信用信息公示系统（江苏）补报年报后即可在线申请移出异常标记，平台不收取手续费。热线 12345。"]', '{"expected_agent_ids": ["cz_scjg_agent"]}', '{"selected_region": "武进区", "route_mode": "auto"}', NULL, '["市场监管", "个体户年报", "信用修复"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.26, 'APPROVED', 'admin', '2026-11-12 13:29:47.136', '盲测集冻结点位（并用于演示 WAF 代码块剥离重试）。', 0, '2026-11-12 15:29:47.143', '2026-11-12 15:29:47.763'),
  (12, 'f479e462d3ba4acea36fae093ef7d6d4', 2, 'gov_holdout_06_youth_rent_sub', 'HOLDOUT', 'MANUAL', NULL, 'SINGLE_TURN', '新来常州企业就业的全日制本科生租房补贴每月多少钱？需要连续缴社保满几个月才能申报？', NULL, '符合“龙城英才计划”条件的新引育全日制本科生租房补贴标准为每月 800 元，需在常州企业依法连续缴纳社会保险满 3 个月并办理房屋租赁备案后线上申报；咨询热线 12333。', NULL, '["常州市青年人才生活居住双资助实施细则：全日制本科生租房补贴 800 元/月，博士 1500 元/月、硕士 1000 元/月；须在常依法连续参保满 3 个月且持有租赁备案证明。咨询电话 12333。"]', '{"expected_agent_ids": ["cz_rs_agent"]}', '{"selected_region": "新北区", "route_mode": "auto"}', NULL, '["人才政策", "租房补贴"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.28, 'APPROVED', 'admin', '2026-11-12 13:29:47.137', '盲测集冻结点位。', 0, '2026-11-12 15:29:47.143', '2026-11-12 15:29:47.779'),
  (13, '399406b2017943728244af3ce3ecded9', 2, 'gov_pending_01_high_uncertainty', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9201", "mining_signal": "USER_DISLIKE"}', 'SINGLE_TURN', '夫妻一方在南京缴公积金、另一方在常州缴公积金，在常州买二手房能按双职工120万算额度吗？', NULL, '异地缴存职工提供《异地贷款职工住房公积金缴存使用证明》及明细且符合连续足额缴存满6个月条件的，可合并按双职工家庭最高额度 120 万元核定；建议拨打 12329 复核二手房房龄折算规则。', NULL, '["常州公积金异地贷款细则：配偶在异地正常连续足额缴存住房公积金满6个月并出具全国统一缴存证明的，合并计算双职工贷款额度（最高120万元）。热线 12329。"]', '{"expected_agent_ids": ["cz_gjj_agent"]}', '{"selected_region": "天宁区", "route_mode": "auto"}', NULL, '["待校准高优", "异地合并额度"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.492, 'PENDING_REVIEW', NULL, NULL, '上一轮模型最低置信度仅 0.508，已自动浮出至主动学习队列首位。', 0, '2026-11-12 15:29:47.144', '2026-11-12 15:29:47.144'),
  (14, '2d95ff655ab54332af37659f25c4c66d', 2, 'gov_pending_02_unmasked_guard_demo', 'DEV', 'MANUAL', NULL, 'SINGLE_TURN', '【演示未脱敏拦截】市民张某某（联系尾号示例 138****0000，当前标记未走脱敏网关）咨询失业保险金每月发放标准怎么算？', NULL, '失业保险金标准根据失业前12个月平均缴费基数的一定比例核定，最高不超过当地最低工资标准、最低不低于城市居民最低生活保障标准的1.5倍；详询 12333。', NULL, '["江苏省失业保险规定：缴费满1年不足10年的按失业前12个月平均缴费基数45%确定，满10年以上的按50%确定，并执行上下限封顶保底。热线 12333。"]', '{"expected_agent_ids": ["cz_rs_agent"]}', '{"selected_region": "钟楼区", "route_mode": "auto"}', NULL, '["安全护栏演示", "未脱敏拦截"]', 'NORMAL', 0, NULL, 0.451, 'PENDING_REVIEW', NULL, NULL, 'pii_masked=0：直接点击『审核通过』将触发后端 400 未脱敏强拦截，勾选已脱敏后方可放行。', 0, '2026-11-12 15:29:47.144', '2026-11-12 15:29:47.144'),
  (15, '8e63795eadf44e86b365d6a24c27e7c4', 2, 'gov_pending_03_med_gap_waiting', 'HOLDOUT', 'ONLINE_MINED', '{"request_id": "req_cz_9203", "mining_signal": "CITY_BACKUP"}', 'SINGLE_TURN', '灵活就业人员职工医保中断缴费4个月后再续缴，住院报销待遇等待期是几个月？', NULL, '灵活就业人员中断缴纳职工医保费超过 3 个月的，重新参保缴费后设置医保待遇等待期（按现行规定执行），等待期内发生的住院医疗费用统筹基金不予支付；详询 12393。', NULL, '["常州市灵活就业人员参加职工基本医疗保险办法：中断缴费超过 3 个月续保的设置待遇等待期，3个月内补齐的视同连续参保。医保热线 12393。"]', '{"expected_agent_ids": ["cz_yb_agent"]}', '{"selected_region": "武进区", "route_mode": "auto"}', NULL, '["医保断缴", "等待期"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.386, 'PENDING_REVIEW', NULL, NULL, '待业务专家确认2026最新固定等待期月数表述。', 0, '2026-11-12 15:29:47.144', '2026-11-12 15:29:47.144'),
  (16, '747412ee35244d78b82a7f02b3494569', 2, 'gov_pending_04_multiturn_upgrade', 'DEV', 'ONLINE_MINED', '{"request_id": "req_cz_9204", "mining_signal": "MULTI_TURN_ESCALATION"}', 'MULTI_TURN', '那原来的统一社会信用代码和门头牌匾还能保留不变吗？', '[{"role": "user", "content": "我在武进开的个体工商户餐饮店现在想升级转成有限责任公司（个转企），直接变更还是要先注销个体户？"}, {"role": "assistant", "content": "常州市支持“个转企”直接变更登记，无需先注销原个体工商户，可通过“个转企一件事”专窗联办营业执照与食品经营许可变更。"}, {"role": "user", "content": "那原来的统一社会信用代码和门头牌匾还能保留不变吗？"}]', '通过“个转企”直接变更登记方式转型的，可依法延续使用原个体工商户的统一社会信用代码及成立日期；字号在符合企业名称登记规则前提下也可最大限度保留。咨询热线 12345。', NULL, '["常州市“个转企”一件事改革实施方案：支持个体工商户直接变更为企业，延续原统一社会信用代码、成立日期，最大限度保留原字号及有效行政许可。热线 12345。"]', '{"expected_agent_ids": ["cz_scjg_agent"]}', '{"selected_region": "武进区", "route_mode": "auto"}', NULL, '["多轮对话", "个转企一件事"]', 'HARD', 1, '{"policy": "gov_eval_corpus:v2.3", "tag_counts": {}}', 0.315, 'PENDING_REVIEW', NULL, NULL, '多轮指代消解待人工终审入库。', 0, '2026-11-12 15:29:47.145', '2026-11-12 15:29:47.145'),
